#include <algorithm>
#include <iostream>
#include <limits>
#include <vector>
using namespace std;

struct Session {
    long long start;
    long long finish;
};

bool ends_earlier(const Session& left, const Session& right) {
    if (left.finish != right.finish) {
        return left.finish < right.finish;
    }
    return left.start < right.start;
}

int max_sessions(vector<Session> sessions) {
    sort(sessions.begin(), sessions.end(), ends_earlier);
    long long last_finish = numeric_limits<long long>::min();
    int selected = 0;

    for (const Session& session : sessions) {
        if (session.start >= last_finish) {
            selected++;
            last_finish = session.finish;
        }
    }

    return selected;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<Session> sessions(n);
    for (Session& session : sessions) {
        cin >> session.start >> session.finish;
    }

    cout << max_sessions(sessions) << '\n';
    return 0;
}

